import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "domains" / "attributes"))

from model import load_payload
from transform import transform


class TestAttributes(unittest.TestCase):
    def test_drop_conflicts(self):
        payload = {
            "attribute_policy": "drop_conflicts",
            "columns": ["a"],
            "pieces": [
                {"id": "p0", "coordinates": [0], "data": [[1]], "attrs": {"site": "0", "unit": "m"}},
                {"id": "p1", "coordinates": [1], "data": [[2]], "attrs": {"site": "1", "unit": "m"}},
            ],
        }
        contract = {"name": "attributes", "operation": "segment_attributes", "inputs": ["x"]}
        result = transform([payload], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "attributes")
        self.assertEqual(result["result"]["attrs"], {"unit": "m"})
        self.assertEqual(result["result"]["conflicts"], ["site"])

    def test_first(self):
        payload = {
            "attribute_policy": "first",
            "columns": ["a"],
            "pieces": [
                {"id": "p0", "coordinates": [0], "data": [[1]], "attrs": {"site": "0"}},
                {"id": "p1", "coordinates": [1], "data": [[2]], "attrs": {"site": "1"}},
            ],
