        contract = {"name": "attributes", "operation": "segment_attributes", "inputs": ["x"]}
        result = transform([payload], contract)
        self.assertEqual(result["result"]["attrs"], {"site": "0"})
        self.assertEqual(result["result"]["conflicts"], [])

    def test_load_payload_rejects_nan(self):
        with self.assertRaises(ValueError):
            load_payload(Path(__file__).with_name("nan.json"))


if __name__ == "__main__":
    unittest.main()

